public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a boolean array to keep track of the visited n-tersections
    boolean[] visited = new boolean[n];
    // Initialize a queue to perform BFS
    Queue<int[]> queue = new LinkedList<>();
    // Mark the starting n-tersection as visited and add it to the queue
    visited[start[0]] = true;
    queue.add(start);

    while (!queue.isEmpty()) {
        // Get the current n-tersection to visit
        int[] current = queue.poll();
        // If the current n-tersection is the ending n-tersection, return "can be travelled"
        if (Arrays.equals(current, end)) {
            return "can be travelled";
        }
        // For each path from the current n-tersection to an adjacent n-tersection
        for (int[] path : paths) {
            if (path[0] == current[0] && !visited[path[1]]) {
                // Mark the adjacent n-tersection as visited and add it to the queue
                visited[path[1]] = true;
                queue.add(new int[]{path[1], path[2]});
            } else if (path[2] == current[0] && !visited[path[1]]) {
                visited[path[1]] = true;
                queue.add(new int[]{path[1], path[2]});
            }
        }
    }

    // If no path was found to the ending n-tersection, return "cannot be travelled"
    return "cannot be travelled";
}

