    while (start <= end) {
        int mid = start + (end - start) / 2;
        int midValue = nums[mid];
        if (midValue == target) {
            return mid;
        }
        int leftValue = nums[start];
        int rightValue = nums[end];
        if (leftValue > midValue && rightValue < midValue) {
            if (leftValue < target) {
                end = mid - 1;
            } else {
                start = mid + 1;
            }
