    public int minOperations(int n) {
        // Initialize the array arr with the given condition
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = (2 * i) + 1;
        }

        // Initialize the count of operations to 0
        int count = 0;

        // Iterate until all elements in arr are equal
        while (!allEqual(arr)) {
            // Find the index of the maximum element in arr
            int maxIndex = maxIndex(arr);
            // Find the index of the minimum element in arr
            int minIndex = minIndex(arr);
            // Subtract 1 from the maximum element and add 1 to the minimum element
            arr[maxIndex] -= 1;
            arr[minIndex] += 1;
            // Increment the count of operations
            count++;
        }

        // Return the count of operations
        return count;
    }

    // Function to check if all elements in arr are equal
    public boolean allEqual(int[] arr) {
        for (int i = 1; i < arr.length; i++) {
            if (arr[i] != arr[0]) {
                return false;
            }
        }
        return true;
    }

    // Function to find the index of the maximum element in arr
    public int maxIndex(int[] arr) {
        int max = arr[0];
        int maxIndex = 0;
        for (int i = 1; i < arr.length; i++) {
            if (arr[i] > max) {
                max = arr[i];
                maxIndex = i;
            }
        }
        return maxIndex;
    }

    // Function to find the index of the minimum element in arr
